import { Backdrop, Box, CircularProgress, Grid } from '@mui/material'
import React, { useEffect, useState } from 'react'
import DashboardCard from '../common/DashboardCard'
import { AiOutlineUser } from "react-icons/ai";
import { GrUserWorker } from "react-icons/gr";
import { FaTasks } from "react-icons/fa";
import { RiMoneyDollarCircleFill } from "react-icons/ri";
import { IoKey } from "react-icons/io5";
import axios from 'axios'
import { useSelector } from 'react-redux';


const baseUrl = process.env.REACT_APP_BASH_URL;

function Home() {
    const user = useSelector((state) => state.user.user);
    const options = { Authorization: `Bearer ${localStorage.getItem("shinpay-vendor-token")}`, "Content-Type": "application/json" };

    const [loading, setLoading] = useState(true)

    const [empCount, setEmpCount] = useState(0)
    const [jobCount, setJobCount] = useState(0)
    const [venderCount, setVenderCount] = useState(0)
    const [planCount, setPlanCount] = useState(0)
    const [apiCount, setApiCount] = useState(0)

    // console.log("user: ", user);
    const getDataCount = async () => {
        return await axios.get(`${baseUrl}/admin/get-count/${user?._id}`, { headers: options }).then((response) => {
            setEmpCount(response.data.result.empCount)
            setJobCount(response.data.result.jobCount)
            setVenderCount(response.data.result.vendorCount)
            setPlanCount(response.data.result.planCount)
            setApiCount(response.data.result.apiCount)
            setLoading(false)
        }).catch((error) => {
            console.log("error on getDataCount: ", error);
            setLoading(false)
        })
    }

    useEffect(() => {
        getDataCount()
    }, [loading])

    return (
        <Box>
            <Backdrop sx={{ color: "#fff", zIndex: (theme) => theme.zIndex.drawer + 1 }} open={loading}>
                <CircularProgress color="inherit" />
            </Backdrop>
            <Grid spacing={2} container>
                <Grid item xs={6}>
                    <DashboardCard title={'Total Vendor'} icon={<AiOutlineUser size={45} color='white' />} count={venderCount ? venderCount : 0} />
                </Grid>

                <Grid item xs={6}>
                    <DashboardCard title={'Total Employee'} icon={<GrUserWorker size={45} color='white' />} count={empCount ? empCount : 0} />
                </Grid>

                <Grid item xs={6}>
                    <DashboardCard title={'Total Plan'} icon={<RiMoneyDollarCircleFill size={45} color='white' />} count={planCount ? planCount : 0} />
                </Grid>

                <Grid item xs={6}>
                    <DashboardCard title={'Total Api Keys'} icon={<IoKey size={45} color='white' />} count={apiCount ? apiCount : 0} />
                </Grid>

            </Grid>
        </Box>
    )
}

export default Home